const items = $input.all();
const now = new Date();
const options = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
const dateStr = now.toLocaleDateString('en-US', options);

if (!items || items.length === 0 || !items[0].json.summary) {
  return [{ json: { formatted_schedule: `*Today's Schedule - ${dateStr}*\n\nYour schedule is free today — nothing on the calendar. Enjoy! 🎉` } }];
}

let msg = `*Today's Schedule - ${dateStr}*\n\n`;

for (const item of items) {
  const e = item.json;
  let timeDisplay = 'All day';
  if (e.start && e.start.dateTime) {
    timeDisplay = new Date(e.start.dateTime).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });
  }
  const location = e.location ? ` - ${e.location}` : '';
  msg += `${timeDisplay} - *${e.summary}*${location}\n`;
}

msg += '\n_Have a productive day!_';

return [{ json: { formatted_schedule: msg } }];

return {
  json: {
    timestamp: new Date().toISOString(),
    trigger_type: 'command',
    command: '/help',
    action_completed: 'true',
    response_time_ms: String(Date.now() - new Date($execution.startedAt).getTime()),
    user_confirmed_before_action: 'n/a',
    confirmation_requested: 'false',
    action_executed: 'false'
  }
};

return {
  json: {
    timestamp: new Date().toISOString(),
    trigger_type: 'command',
    command: '/today',
    action_completed: 'true',
    response_time_ms: String(Date.now() - new Date($execution.startedAt).getTime()),
    user_confirmed_before_action: 'n/a',
    confirmation_requested: 'false',
    action_executed: 'true'
  }
};

const triggerData = $('Telegram Trigger').first().json;
const messageText = triggerData.message && triggerData.message.text ? triggerData.message.text : '';
const isCommand = messageText.startsWith('/');
const agentOutput = $json.output || $json.text || '';

const confirmationRequested = agentOutput.includes('[CONFIRMATION REQUESTED]');
const actionExecuted = agentOutput.includes('[ACTION EXECUTED]');

let userConfirmedBeforeAction = 'n/a';
if (actionExecuted) userConfirmedBeforeAction = 'yes';
else if (confirmationRequested) userConfirmedBeforeAction = 'pending';

return {
  json: {
    timestamp: new Date().toISOString(),
    trigger_type: isCommand ? 'command' : 'freeform',
    command: isCommand ? messageText.split(' ')[0] : 'freeform_text',
    action_completed: actionExecuted ? 'true' : (confirmationRequested ? 'pending' : 'responded'),
    response_time_ms: String(Date.now() - new Date($execution.startedAt).getTime()),
    user_confirmed_before_action: userConfirmedBeforeAction,
    confirmation_requested: confirmationRequested ? 'true' : 'false',
    action_executed: actionExecuted ? 'true' : 'false'
  }
};

const triggerData = $('Telegram Trigger').first().json;
const messageText = triggerData.message && triggerData.message.text ? triggerData.message.text : '';
const isCommand = messageText.startsWith('/');
return {
  json: {
    timestamp: new Date().toISOString(),
    trigger_type: isCommand ? 'command' : 'freeform',
    command: isCommand ? messageText.split(' ')[0] : 'freeform_text',
    action_completed: 'cancelled',
    response_time_ms: String(Date.now() - new Date($execution.startedAt).getTime()),
    user_confirmed_before_action: 'no',
    confirmation_requested: 'true',
    action_executed: 'false'
  }
};
